// The drum grooves (docs/drums.md), as the engine lists them: generated by `sedef-params --grooves`.
import generated from '../generated/grooves.json';

export interface Groove {
  /** The drumsGroove parameter's value for this groove. */
  index: number;
  name: string;
  /** One line on how it feels, for the groove picker. */
  feel: string;
  /** The metronomeSignature choice it is written in. */
  signature: number;
}

export const GROOVES: readonly Groove[] = generated.grooves.map((g, index) => ({ index, ...g }));

/** The grooves written in a signature, in list order. */
export function groovesFor(signature: number): Groove[] {
  return GROOVES.filter((g) => g.signature === signature);
}

/**
 * The groove that plays for a drumsGroove value in a signature: that groove when it is written in
 * the signature, otherwise the signature's first (sedef::dsp::drums::grooveFor).
 */
export function grooveFor(groove: number, signature: number): number {
  const index = Math.min(Math.max(Math.round(groove), 0), GROOVES.length - 1);
  if (GROOVES[index]?.signature === signature) return index;
  return groovesFor(signature)[0]?.index ?? index;
}

/** drumsFills choices as the panel shows them, under the label "Fill every". */
export const FILL_LABELS = ['Off', '2 bars', '4 bars', '8 bars'] as const;
